import{_ as a,r as o,o as d,c as t,a as i,b as s,d as n,e as r}from"./app.ChrdILIc.js";import"./chunks/three-vendor.DK3fmyXa.js";const g=JSON.parse('{"title":"Codex 介绍与用法","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ai/codex.md","filePath":"zh/ai/codex.md","lastUpdated":1778395361000}'),p={name:"zh/ai/codex.md"};function h(c,e,u,x,b,C){const l=o("ArticleMetadata");return d(),t("div",null,[e[0]||(e[0]=i("h1",{id:"codex-介绍与用法",tabindex:"-1"},[s("Codex 介绍与用法 "),i("a",{class:"header-anchor",href:"#codex-介绍与用法","aria-label":'Permalink to "Codex 介绍与用法"'},"​")],-1)),n(l),e[1]||(e[1]=r(`<blockquote><p>本文基于 OpenAI 官方产品页、官方开发文档与帮助中心整理，重点介绍 Codex 的定位、使用入口、适用场景与基础上手方式。</p></blockquote><h2 id="一、codex-是什么" tabindex="-1">一、Codex 是什么 <a class="header-anchor" href="#一、codex-是什么" aria-label="Permalink to &quot;一、Codex 是什么&quot;">​</a></h2><p>Codex 是 OpenAI 的编码 Agent。官方将它定义为可以“读代码、改代码、运行代码”的 coding agent，用来帮助开发者完成从理解代码、修复 Bug、生成测试，到重构、迁移和代码审查等真实工程任务。</p><p>和传统代码补全工具相比，Codex 的定位更偏向“可执行任务的工程助手”，而不是只在你输入时做局部补全。</p><p>OpenAI 官方产品页强调了几件事：</p><ul><li>它不仅能生成代码，还能完成端到端工程任务</li><li>它支持多 Agent 并行工作</li><li>它既能本地配合开发，也能把任务委托到云端后台执行</li><li>它可以贯通 Web、IDE、CLI、GitHub 等多个入口</li></ul><h2 id="二、codex-的核心能力" tabindex="-1">二、Codex 的核心能力 <a class="header-anchor" href="#二、codex-的核心能力" aria-label="Permalink to &quot;二、Codex 的核心能力&quot;">​</a></h2><h3 id="_1-读、改、跑一体化" tabindex="-1">1. 读、改、跑一体化 <a class="header-anchor" href="#_1-读、改、跑一体化" aria-label="Permalink to &quot;1. 读、改、跑一体化&quot;">​</a></h3><p>Codex 不是只返回一段建议代码，而是会：</p><ul><li>读取仓库上下文</li><li>修改多个文件</li><li>执行命令或测试</li><li>生成可审查的修改结果</li></ul><p>这也是它和传统“对话式代码问答”最大的区别。</p><h3 id="_2-云端后台任务" tabindex="-1">2. 云端后台任务 <a class="header-anchor" href="#_2-云端后台任务" aria-label="Permalink to &quot;2. 云端后台任务&quot;">​</a></h3><p>OpenAI 在官方文档中把这一能力叫做 <code>Codex cloud</code>。你可以把任务交给 Codex 在云端隔离环境中执行，它会自己拉起代码和依赖，在后台工作。</p><p>这适合：</p><ul><li>长耗时重构</li><li>大仓库代码审查</li><li>并行跑多个任务</li><li>不想长时间卡在本地终端前的场景</li></ul><h3 id="_3-多入口一致体验" tabindex="-1">3. 多入口一致体验 <a class="header-anchor" href="#_3-多入口一致体验" aria-label="Permalink to &quot;3. 多入口一致体验&quot;">​</a></h3><p>官方资料显示，Codex 目前主要有这些入口：</p><ul><li>Codex Web</li><li>Codex CLI</li><li>IDE 扩展</li><li>GitHub 相关工作流</li></ul><p>OpenAI 的设计思路是：这些入口由同一个 ChatGPT 账号串联，方便在本地和云端之间切换。</p><h3 id="_4-更适合-agent-化工作流" tabindex="-1">4. 更适合 Agent 化工作流 <a class="header-anchor" href="#_4-更适合-agent-化工作流" aria-label="Permalink to &quot;4. 更适合 Agent 化工作流&quot;">​</a></h3><p>Codex 官方产品页强调了几项比较“Agent 化”的能力：</p><ul><li>多 Agent 并行</li><li>Skills</li><li>Automations</li><li>云环境执行</li><li>更偏任务流而不是单轮问答</li></ul><p>所以它适合写功能、改代码、审 PR，也适合更长期的工程自动化。</p><h2 id="三、如何使用-codex" tabindex="-1">三、如何使用 Codex <a class="header-anchor" href="#三、如何使用-codex" aria-label="Permalink to &quot;三、如何使用 Codex&quot;">​</a></h2><h3 id="方式一-使用-codex-web" tabindex="-1">方式一：使用 Codex Web <a class="header-anchor" href="#方式一-使用-codex-web" aria-label="Permalink to &quot;方式一：使用 Codex Web&quot;">​</a></h3><p>这是 OpenAI 官方文档中最直接的上手路径。</p><p>根据官方 Codex Cloud 文档，开始方式是：</p><ol><li>打开 <code>chatgpt.com/codex</code></li><li>连接 GitHub 账号</li><li>选择仓库</li><li>把任务交给 Codex</li></ol><p>官方说明指出，Codex Web 适合在云端后台委派任务，例如：</p><ul><li>分析代码库</li><li>修复 Bug</li><li>生成测试</li><li>起草 PR</li><li>代码审查</li></ul><h3 id="方式二-使用-codex-cli" tabindex="-1">方式二：使用 Codex CLI <a class="header-anchor" href="#方式二-使用-codex-cli" aria-label="Permalink to &quot;方式二：使用 Codex CLI&quot;">​</a></h3><p>OpenAI 官方产品页与帮助中心都提到，Codex 可以在终端中使用。</p><p>常见安装命令：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @openai/codex</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后登录并开始工作。OpenAI 的上手页给出的最基础流程是：</p><ol><li>打开 Codex</li><li>使用 ChatGPT 账号登录</li><li>选择一个本地文件夹或 Git 仓库</li><li>发起第一个任务</li></ol><p>CLI 更适合：</p><ul><li>本地仓库协作</li><li>终端开发流</li><li>和现有 shell / git / test 工具链一起工作</li></ul><h3 id="方式三-使用-ide-扩展" tabindex="-1">方式三：使用 IDE 扩展 <a class="header-anchor" href="#方式三-使用-ide-扩展" aria-label="Permalink to &quot;方式三：使用 IDE 扩展&quot;">​</a></h3><p>OpenAI 帮助中心指出，Codex 的 VS Code 扩展兼容大多数 VS Code fork，并且也能在 IDE 自带终端中运行 CLI。</p><p>目前官方明确提到的典型 IDE / 编辑器路径包括：</p><ul><li>VS Code</li><li>Cursor</li><li>Windsurf</li></ul><p>如果你的开发主场景就是编辑器，那么 IDE 扩展会比纯 Web 更自然。</p><h2 id="四、codex-的适用场景" tabindex="-1">四、Codex 的适用场景 <a class="header-anchor" href="#四、codex-的适用场景" aria-label="Permalink to &quot;四、Codex 的适用场景&quot;">​</a></h2><p>Codex 最适合以下几类任务：</p><h3 id="_1-新功能开发" tabindex="-1">1. 新功能开发 <a class="header-anchor" href="#_1-新功能开发" aria-label="Permalink to &quot;1. 新功能开发&quot;">​</a></h3><p>例如：</p><ul><li>新建模块</li><li>增加接口</li><li>页面改版</li><li>自动补测试</li></ul><h3 id="_2-bug-修复" tabindex="-1">2. Bug 修复 <a class="header-anchor" href="#_2-bug-修复" aria-label="Permalink to &quot;2. Bug 修复&quot;">​</a></h3><p>官方文档中特别适合这种写法：</p><ul><li>给出报错信息</li><li>指定目标仓库或目标文件</li><li>让 Codex 直接定位并修复问题</li></ul><h3 id="_3-代码审查与改进建议" tabindex="-1">3. 代码审查与改进建议 <a class="header-anchor" href="#_3-代码审查与改进建议" aria-label="Permalink to &quot;3. 代码审查与改进建议&quot;">​</a></h3><p>Codex 适合阅读 diff、审 PR、找边界条件问题，以及提出重构建议。</p><h3 id="_4-理解陌生代码库" tabindex="-1">4. 理解陌生代码库 <a class="header-anchor" href="#_4-理解陌生代码库" aria-label="Permalink to &quot;4. 理解陌生代码库&quot;">​</a></h3><p>例如：</p><ul><li>画请求链路图</li><li>解释模块关系</li><li>梳理数据库到接口的流程</li><li>生成架构说明</li></ul><p>这类“理解型任务”在大项目里很有价值。</p><h2 id="五、如何写更适合-codex-的任务" tabindex="-1">五、如何写更适合 Codex 的任务 <a class="header-anchor" href="#五、如何写更适合-codex-的任务" aria-label="Permalink to &quot;五、如何写更适合 Codex 的任务&quot;">​</a></h2><p>Codex 对“工程型描述”比较友好。比起一句很泛的“帮我改下代码”，更推荐写成：</p><ul><li>目标是什么</li><li>修改范围在哪里</li><li>要不要动代码</li><li>需要不要补测试</li><li>输出期望是什么</li></ul><p>例如：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请检查用户登录流程的异常处理，定位登录失败时未提示错误信息的问题。</span></span>
<span class="line"><span>修改代码并补充测试，不要改动数据库结构。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>或者：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阅读这个仓库，给我解释从前端请求到数据库写入的完整链路，并生成 mermaid 图。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这种写法通常比模糊指令更稳定。</p><h2 id="六、codex-的账号与计划说明" tabindex="-1">六、Codex 的账号与计划说明 <a class="header-anchor" href="#六、codex-的账号与计划说明" aria-label="Permalink to &quot;六、Codex 的账号与计划说明&quot;">​</a></h2><p>根据 OpenAI 官方帮助中心与 Codex 文档，目前 Codex 与 ChatGPT 计划是打通的。</p><p>官方页面提到，Codex 可通过以下计划接入：</p><ul><li>Plus</li><li>Pro</li><li>Business</li><li>Edu</li><li>Enterprise</li></ul><p>另外，帮助中心也说明：</p><ul><li>不同计划的使用额度不同</li><li>任务复杂度会影响额度消耗</li><li>CLI 和 IDE 扩展默认使用的具体模型，取决于版本与配置</li></ul><h2 id="七、codex-的数据与权限说明" tabindex="-1">七、Codex 的数据与权限说明 <a class="header-anchor" href="#七、codex-的数据与权限说明" aria-label="Permalink to &quot;七、Codex 的数据与权限说明&quot;">​</a></h2><p>OpenAI 帮助中心对数据使用说明比较明确：</p><ul><li>Business、Enterprise、Edu 默认不使用业务用户输入输出来训练模型</li><li>API 组织所有者可以选择是否共享 API 数据</li><li>Plus、Pro 用户如果没有关闭相应数据控制，聊天内容可能用于改进模型</li></ul><p>如果你用于公司项目，最好优先：</p><ul><li>了解所在组织的 ChatGPT / API 数据策略</li><li>使用团队或企业计划</li><li>对仓库权限和云任务环境做最小化授权</li></ul><h2 id="八、codex-适合谁" tabindex="-1">八、Codex 适合谁 <a class="header-anchor" href="#八、codex-适合谁" aria-label="Permalink to &quot;八、Codex 适合谁&quot;">​</a></h2><p>Codex 更适合：</p><ul><li>日常写代码的开发者</li><li>需要本地和云端都能协作的人</li><li>需要审 PR、补测试、做重构的人</li><li>想让 AI 真正参与工程流程，而不是只做补全的人</li></ul><p>如果你要的是“本地命令行 Agent + ChatGPT 账号打通 + 云端并行任务”，Codex 是很值得单独了解的一条产品线。</p>`,80))])}const q=a(p,[["render",h]]);export{g as __pageData,q as default};
